'use strict';

function normalizeTerm(value) {
  const selected = String(value || '').trim()
    .replace(/^[\s"'""''《》〈〉【】\[\]（）()，。！？、；：;:,]+/, '')
    .replace(/[\s"'""''《》〈〉【】\[\]（）()，。！？、；：;:,]+$/, '');
  return selected.slice(0, 64);
}

module.exports.dictionary = async function (input) {
  const value = input || {};
  const term = normalizeTerm(value.word || value.context);
  if (!term) {
    return { title: 'AI中医辞典', text: '请选中需要查询的中医词语。' };
  }
  if (term.length > 32) {
    return { title: term + ' · AI中医辞典', text: '选中内容过长，请选择单个中医术语。' };
  }

  try {
    const baikeUrl = "https://baike.baidu.com/api/openapi/BaikeLemmaCardApi?scope=103&format=json&appid=379020&bk_key=" + encodeURIComponent(term) + "&bk_length=600";

    const response = await reader.http.fetch({
      url: baikeUrl,
      method: "GET",
      timeoutMs: 15000
    });

    const status = Number(response && response.status || 0);
    const bodyText = String(response && response.body || "");

    if (status < 200 || status >= 400) {
      return {
        title: term + ' · AI中医辞典',
        text: "百度百科接口请求失败 HTTP: " + status + "\n返回：" + bodyText.slice(0, 400)
      };
    }

    let data;
    try {
      data = JSON.parse(bodyText);
    } catch (_e) {
      return {
        title: term + ' · AI中医辞典',
        text: "百度百科返回非 JSON：" + bodyText.slice(0, 500)
      };
    }

    let output = "";
    let found = false;

    if (data) {
      const keys = Object.keys(data);
      for (let i = 0; i < keys.length; i++) {
        const k = keys[i];
        const v = data[k];
        if (k === "key" || k === "card") {
          if (v && typeof v === "object") {
            if (v.name || v.key) {
              output += "【词条】" + (v.name || v.key) + "\n\n";
              found = true;
            }
            if (v.abs || v.abstract || v.desc) {
              output += "【释义】\n" + (v.abs || v.abstract || v.desc) + "\n\n";
              found = true;
            }
            if (v.url) {
              output += "【来源】" + v.url + "\n";
            }
          }
        }
        if (k === "abstract" || k === "abs" || k === "desc") {
          if (v && typeof v === "string" && v.length > 10) {
            output += "【释义】\n" + v + "\n\n";
            found = true;
          }
        }
        if (k === "url") {
          output += "【来源】" + v + "\n";
        }
      }
    }

    if (!found) {
      return {
        title: term + " · AI中医辞典",
        text: "未找到「" + term + "」的百科释义。\n\n" +
              "可能原因：\n" +
              "• 该词条尚未被百度百科收录\n" +
              "• 词条名称不够规范\n\n" +
              "建议尝试更通用的说法，例如：\n" +
              "• 「四诊」而非「四诊法」\n" +
              "• 「当归」而非「当归功效」\n\n" +
              "⚠ 内容仅供学习，不作为医疗诊断依据"
      };
    }

    output += "\n⚠ 内容来自百度百科，仅供学习，不作为医疗诊断依据";

    return {
      title: term + " · AI中医辞典",
      text: output
    };

  } catch (error) {
    const message = (error && error.message ? String(error.message) : String(error || "未知错误")).slice(0, 500);
    return {
      title: term + ' · AI中医辞典',
      text: "查询异常：" + message + "\n\n提示：请检查网络连接。"
    };
  }
};
